/* eslint-disable no-undef */
import { Component, Element, Event, EventEmitter, Host, Prop, h } from '@stencil/core';
import { LoadingSpinnerVariant, ProgressCircleBackground, Severity } from '../../types';

@Component({
  tag: 'groupui-loading-spinner',
  styleUrl: 'loading-spinner.scss',
  shadow: true,
})
export class LoadingSpinner {
  /**
   * variant of the loading spinner
   */
  @Prop({ reflect: true }) readonly variant: LoadingSpinnerVariant;

  /**
   * severity of the loading spinner
   */
  @Prop({ reflect: true }) readonly severity: Severity;

  /**
   * defines the color of the backdrop
   */
  @Prop({ reflect: true }) readonly background: ProgressCircleBackground;

  /**
   * defines if the loading indicator is visible.
   */
  @Prop() readonly displayed: boolean;

  /**
   * defines the duration of one loading animation spin in seconds
   */
  @Prop({ reflect: true }) readonly duration: string = '1.5s';

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  private isSafariUserAgent() {
    return (
      window.navigator.userAgent.indexOf('Safari') > 0 &&
      window.navigator.userAgent.indexOf('Chrome') === -1 &&
      window.navigator.userAgent.indexOf('Chromium') === -1
    );
  }

  private getSpinner() {
    const isSafari = this.isSafariUserAgent();
    return `<svg class="circle-progress__svg" viewBox="0 0 35 35">
                  <circle class="svg__background" cx="17.5" cy="17.5" r="15" />
                  <circle style="transform-origin: ${
                    isSafari ? 'revert' : 'center'
                  }" class="svg__fill" cx="17.5" cy="17.5" r="15" stroke-dasharray="45">
                    <!-- safari interprets rotate different, we have to set exact half of the viewbox as center -->
                    <animateTransform
                      attributeName="transform"
                      type="rotate"
                      from="${isSafari ? '0 17.5 17.5' : '0 0 0'}"
                      to="${isSafari ? '360 17.5 17.5' : '360 0 0'}"
                      dur="${this.duration}"
                      repeatCount="indefinite"
                    />
                  </circle>
                </svg>`;
  }

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  render() {
    return (
      <Host>
        {this.displayed && (
          <div class="backdrop">
            <div id="loading-spinner">
              <div class="circle-progress circle-progress--animation" innerHTML={this.getSpinner()} />
            </div>
          </div>
        )}
      </Host>
    );
  }
}
